const r = phi.goto("https://new.mta.info/");
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 8000 });
return { r, title: phi.tabs.list() };

const t = phi.text();
const links = phi.query("a", { fields: ["href", "text"], limit: 200 });
const nb = links.items.filter(l => /neighborhood|brooklyn/i.test((l.text||"") + " " + (l.href||"")));
return { len: t.length, textTail: t.slice(1500, 8000), nb };

const r = phi.goto("https://new.mta.info/maps/neighborhood-maps");
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 8000 });
const t = phi.text();
const links = phi.query("a", { fields: ["href", "text"], limit: 300 });
const br = links.items.filter(l => /brooklyn/i.test((l.text||"") + " " + (l.href||"")));
return { url: r.url, title: r.title, len: t.length, head: t.slice(0, 2500), brooklynLinks: br, totalLinks: links.total };

const t = phi.text();
const docs = phi.query("a[href*='/document/']", { fields: ["href", "text"], limit: 400 });
return { len: t.length, head: t.slice(0, 1500), docCount: docs.total, docsSample: docs.items.slice(0, 40) };

const docs = phi.query("a[href*='/document/']", { fields: ["href", "text"], limit: 400 });
const items = docs.items.map(d => ({ n: d.text.trim(), u: d.href }));
phi.keep("bk-neighborhood-maps", { total: docs.total, page: "https://www.mta.info/maps/neighborhood-maps/brooklyn", items });
const uniq = new Set(items.map(i => i.u));
return { total: docs.total, got: items.length, uniqueUrls: uniq.size, first3: items.slice(0,3), last3: items.slice(-3) };

const home = phi.goto("https://new.mta.info/");
const start = { url: home.url, title: home.title };
const bk = phi.goto("https://www.mta.info/maps/neighborhood-maps/brooklyn");
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 8000 });
const h1 = phi.query("h1", { limit: 3 });
const links = phi.query("a[href*='/document/']", { fields: ["href", "text"], limit: 5 });
phi.look();
return { start, bkUrl: bk.url, bkTitle: bk.title, h1: h1.items.map(x => x.text), firstLinks: links.items, totalDocs: links.total };

const d = phi.recall("bk-neighborhood-maps");
const names = d.items.map(i => i.n.trim());
const compact = names.join(' | ');
phi.keep("bk-final", { page: d.page, total: d.total, names: compact });
return { count: names.length, unique: new Set(names).size, chars: compact.length };

const obs = phi.query("h2, h3, main p", { limit: 20 });
const counts = phi.js(() => {
  const links = Array.from(document.querySelectorAll("a[href*='/document/']"));
  const groups = {};
  links.forEach(a => {
    let p = a.closest("section, ul, div");
    let key = (p && (p.getAttribute("id") || p.className)) || "none";
    groups[key] = (groups[key] || 0) + 1;
  });
  const pag = Array.from(document.querySelectorAll("a[href*='page='], .pager a, nav[aria-label*='agination'] a")).map(a => a.textContent.trim() + " -> " + a.getAttribute("href"));
  return { groups, pagCount: pag.length, pag, docCount: links.length, hasNext: !!document.querySelector("a[rel='next']") };
});
return { headings: obs.items.map(i => i.text.slice(0,120)), js: counts };

const info = phi.js(() => {
  const links = Array.from(document.querySelectorAll("a[href*='/document/']"));
  const sample = links.slice(0, 3).concat(links.slice(80, 83), links.slice(-3)).map(a => {
    const r = a.getBoundingClientRect();
    return { t: a.textContent.trim(), vis: r.width > 0 && r.height > 0, href: a.getAttribute("href") };
  });
  const names = links.map(a => a.textContent.trim());
  const sorted = names.slice().sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
  const sameOrder = names.every((n, i) => n === sorted[i]);
  const inputs = Array.from(document.querySelectorAll("input, select, [role='searchbox']")).map(e => (e.getAttribute("placeholder") || e.id || e.name || e.type || "").slice(0, 40));
  return { count: links.length, sample, sameOrder, firstVisibleY: Math.round(links[0].getBoundingClientRect().top), lastVisibleY: Math.round(links[links.length-1].getBoundingClientRect().top), inputs };
});
phi.scroll({ dy: 2000 });
phi.look();
const saved = phi.recall("bk-final");
phi.keep("bk-verify", { count: info.count, alphabetical: info.sameOrder, visibleLinks: info.sample.every(s => s.vis), inputs: info.inputs });
return info;

phi.scroll({ dy: -8000 });
const check = phi.js(() => {
  const h = Array.from(document.querySelectorAll("h1")).map(e => e.textContent.trim());
  const links = Array.from(document.querySelectorAll("a[href*='/document/']"));
  const sel = document.querySelector("select");
  const opts = sel ? Array.from(sel.options).map(o => o.textContent.trim() + " => " + o.value) : [];
  const intro = document.body.innerText.slice(0, 400);
  return { h1: h, count: links.length, options: opts, intro };
});
phi.look();
return check;

const nav = phi.goto("https://new.mta.info/");
const landed = { url: nav.url, title: nav.title };
const fin = phi.recall("bk-final");
const names = typeof fin.names === "string" ? fin.names.split(" | ") : [];
phi.keep("bk-answer", { startLanded: landed, sourcePage: "https://www.mta.info/maps/neighborhood-maps/brooklyn", h1: "Brooklyn neighborhood maps", total: names.length, names });
return { landed, total: names.length, first: names.slice(0,5), last: names.slice(-5) };

const nav = phi.goto("https://new.mta.info/maps/neighborhood-maps/brooklyn");
const info = phi.js(() => {
  const h1 = Array.from(document.querySelectorAll("h1")).map(e => e.textContent.trim());
  const links = Array.from(document.querySelectorAll("a[href*='/document/']"));
  const body = document.body.innerText;
  const idx = body.indexOf("neighborhood maps");
  return { h1, count: links.length, first: links.slice(0,3).map(a=>a.textContent.trim()), last: links.slice(-3).map(a=>a.textContent.trim()), intro: body.slice(idx, idx+400) };
});
phi.keep("bk-newdomain", { requested: "https://new.mta.info/maps/neighborhood-maps/brooklyn", landedUrl: nav.url, title: nav.title, h1: info.h1, count: info.count, intro: info.intro });
return { landed: nav.url, title: nav.title, h1: info.h1, count: info.count, first: info.first, last: info.last, intro: info.intro };

const a = phi.recall("bk-answer");
const names = a.names;
phi.keep("brooklyn-maps-final", {
  requestedEntry: "https://new.mta.info/",
  redirect: "new.mta.info → https://www.mta.info/ (Home | MTA)",
  page: a.sourcePage,
  pageH1: a.h1,
  total: names.length,
  names
});
return { total: names.length, sample: names.slice(0, 6), tail: names.slice(-6), dupCheck: (new Set(names)).size };

const nav = phi.goto("https://new.mta.info/maps/neighborhood-maps/brooklyn");
const info = phi.js(() => {
  const h1 = document.querySelector("h1") ? document.querySelector("h1").textContent.trim() : null;
  const links = Array.from(document.querySelectorAll("a[href*='/document/']")).filter(a => a.offsetParent !== null);
  return { h1, visible: links.length, text: document.body.innerText.slice(0, 300) };
});
